mapper.select:
SELECT a.birth_date AS birthDate,a.user_code AS usercode,a.user_name AS username,a.name, CASE WHEN a.gender = 1 THEN '男' ELSE '女' END AS sex, c.report_desc AS reportDesc,c.report_score AS reportScore,c.report_level AS reportLevel,c.qtime AS qtime FROM yh_user_reginfo AS a INNER JOIN yh_user_make_card AS b ON a.user_code=b.user_code INNER JOIN yh_sleep_report AS c ON a.user_code=c.user_code where b.doctor=(SELECT id FROM yh_user_admin_info WHERE user_code=#{userCode,jdbcType=VARCHAR})
and c.report_level=#{reportLevel}
and a.name LIKE CONCAT('%',#{name},'%')
and a.user_name LIKE CONCAT('%',#{userName},'%')
and qtime between #{qtime} and #{qtime1}
order by qtime desc LIMIT #{page},#{limit}

SELECT count(*) FROM yh_user_reginfo AS a INNER JOIN yh_user_make_card AS b ON a.user_code=b.user_code INNER JOIN yh_sleep_report AS c ON a.user_code=c.user_code where b.doctor=(SELECT id FROM yh_user_admin_info WHERE user_code=#{userCode,jdbcType=VARCHAR})
and c.report_level=#{reportLevel}
and a.name LIKE CONCAT('%',#{name},'%')
and a.user_name LIKE CONCAT('%',#{userName},'%')
and qtime between #{qtime} and #{qtime1}

select * from (SELECT a.birth_date AS birthDate,a.user_code AS usercode,a.user_name AS username,a.name, CASE WHEN a.gender = 1 THEN '男' ELSE '女' END AS sex, c.report_desc AS reportDesc,c.report_score AS reportScore,c.report_level AS reportLevel,c.qtime AS qtime FROM yh_user_reginfo AS a INNER JOIN yh_user_make_card AS b ON a.user_code=b.user_code INNER JOIN yh_sleep_report AS c ON a.user_code=c.user_code
b.doctor=(SELECT id FROM yh_user_admin_info WHERE user_code=#{userCode,jdbcType=VARCHAR})
and c.report_level=#{reportLevel}
and a.name LIKE CONCAT('%',#{name},'%')
and a.org_code LIKE CONCAT('%',#{orgCode},'%')
) w group by usercode order by qtime desc LIMIT #{page},#{limit}

